const D = { dots: .5, scale: 1, hue: 200, energy: .6, spin: 1, speed: 1, density: .55, x: .5, y: .26, style: 'specular', act: 'glide', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;

const STY = {
  specular:  { wire:false, facet:[210,7,58],  glint:[200,5,100],  rim:[210,10,82], dotSat:38, dotBri:100, iri:0 },
  wireframe: { wire:true,  facet:[190,65,52], glint:[188,35,100], rim:[190,75,92], dotSat:72, dotBri:100, iri:0 },
  chrome:    { wire:false, facet:[280,24,54], glint:[300,30,100], rim:[280,22,84], dotSat:56, dotBri:100, iri:1 },
  noir:      { wire:false, facet:[220,3,42],  glint:[220,1,100],  rim:[0,0,92],    dotSat:6,  dotBri:96,  iri:0 },
  riso:      { wire:false, facet:[350,58,66], glint:[188,52,100], rim:[350,62,84], dotSat:74, dotBri:98,  iri:0 }
};
const st = STY[P.style] || STY.specular;

const cx = P.x * width, cy = P.y * height;
const R = u * (0.09 + P.scale * 0.11);

// ---- section / act ----
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const arc = [.3,.5,.7,.9,.4,.7,1,.5][sec];
const ACT = {
  glide:   { spinM: 1,               throwR: 1,          spk: 1 },
  throb:   { spinM: 1 + K.pulse*1.4,  throwR: 1,          spk: 1.3 },
  scatter: { spinM: 1.35,             throwR: 1.5+arc*.5, spk: 1.6 }
};
const act = ACT[P.act] || ACT.glide;

// continuous rotation (K.t monotonic -> never re-phases)
const spin = K.t * P.spin * P.speed * 0.6 * act.spinM;

// ---- seeded facet grid on unit sphere (geometry only) ----
if (S.geoUsed !== P.seed + '|' + P.density) {
  S.geoUsed = P.seed + '|' + P.density;
  const rows = Math.round(6 + P.density * 6);
  const F = [];
  for (let r = 0; r < rows; r++) {
    const la = -Math.PI/2 + Math.PI * (r + 0.5) / rows;
    const cols = Math.max(3, Math.round(Math.cos(la) * rows * 2.2));
    for (let c = 0; c < cols; c++) {
      const lo = (c / cols) * TAU + fr(r*31 + c)*0.15;
      F.push({ la, lo, j: fr(r*57 + c*13), sz: 1 / cols });
      if (F.length >= 150) break;
    }
    if (F.length >= 150) break;
  }
  S.F = F;
}
const F = S.F;

const light = [-0.5, 0.62, 0.6];
const lm = Math.hypot(light[0], light[1], light[2]);
light[0]/=lm; light[1]/=lm; light[2]/=lm;

// ---- chain ----
push();
stroke(st.rim[0], st.rim[1]*0.5, st.rim[2]*0.7, 55);
strokeWeight(Math.max(1, u*0.0015));
line(cx, 0, cx, cy - R*0.98);
noStroke();
// ceiling mount
fill(0,0,st.rim[2]*0.5, 60); ellipse(cx, 0, u*0.02, u*0.01);
pop();

// ---- ball rim shadow disc ----
push();
if (!st.wire) { noStroke(); fill(st.facet[0], st.facet[1], st.facet[2]*0.35, 70); ellipse(cx, cy, R*2.06, R*2.06); }
pop();

// ---- facets ----
push();
if (st.wire) { strokeWeight(Math.max(0.8, u*0.0011)); }
else noStroke();
const fs = R * 0.9;
for (let i = 0; i < F.length; i++) {
  const f = F[i];
  const lo = f.lo + spin;
  const x = Math.cos(f.la) * Math.sin(lo);
  const y = Math.sin(f.la);
  const z = Math.cos(f.la) * Math.cos(lo);
  if (z <= 0.02) continue;
  const sx = cx + x * R, sy = cy - y * R;
  const ndl = Math.max(0, x*light[0] + y*light[1] + z*light[2]);
  const spec = Math.pow(ndl, 3.2);
  const twinkle = Math.pow(Math.max(0, Math.sin(K.t*(2.2 + f.j*4) + i*1.7)), 10);
  const spark = (twinkle * 0.7 + A.treble * fr(i+3) * 0.9) * act.spk;
  const lit = 0.28 + 0.5*ndl*z + spec*0.5 + spark;
  const size = fs * f.sz * (2.0 + f.j*0.6) * (0.85 + z*0.3);
  let hh = st.facet[0], ss = st.facet[1], bb = st.facet[2];
  if (st.iri) { hh = hw(st.facet[0] + Math.atan2(y, x)*40 + spin*30); ss = st.facet[1] + 20*ndl; }
  bb = Math.min(100, bb * (0.4 + lit*1.1));
  if (st.wire) { stroke(hh, ss, Math.min(100, 40 + lit*70), 40 + z*40); noFill(); }
  else { fill(hh, ss, bb, 88); }
  rect(sx - size/2, sy - size/2, size, size, size*0.12);
  // glint on strongest facets
  if (!st.wire && (spec > 0.55 || spark > 0.5)) {
    fill(st.glint[0], st.glint[1], st.glint[2], 70 + spark*30);
    ellipse(sx, sy, size*0.4, size*0.4);
  }
}
pop();

// ---- ball rim highlight ----
push();
noFill(); stroke(st.rim[0], st.rim[1], st.rim[2], 45); strokeWeight(Math.max(1, u*0.002));
ellipse(cx, cy, R*2, R*2);
// top specular kiss
noStroke(); blendMode(ADD);
fill(st.glint[0], st.glint[1]*0.5, 100, 30);
ellipse(cx - R*0.32, cy - R*0.34, R*0.6, R*0.6);
blendMode(BLEND);
pop();

// ---- thrown light dots sweeping the room ----
push();
blendMode(ADD); noStroke();
const nDots = Math.round(6 + P.dots * 44);
for (let i = 0; i < nDots; i++) {
  const spd = 0.35 * (1 + fr(i+5)*0.7) * P.spin * P.speed;
  const ang = fr(i)*TAU + K.t * spd;
  const rx = (0.16 + fr(i+9)*0.86) * act.throwR;
  const ry = (0.14 + fr(i+11)*0.82) * act.throwR;
  const px = cx + Math.cos(ang) * rx * width * 0.92;
  const py = cy + Math.sin(ang*0.83 + fr(i+3)*TAU) * ry * height * 0.9;
  const tw = 0.35 + 0.65*Math.pow(Math.max(0,Math.sin(K.t*(1.1+fr(i)*3.4)+i*2.1)), 6)
             + A.treble*fr(i+7)*1.1*act.spk;
  const bri = Math.min(100, st.dotBri * (0.5 + tw*0.6));
  const dh = hw(P.hue + (fr(i)-0.5)*70);
  const sz = u * (0.008 + fr(i+2)*0.03) * (0.5 + tw*0.7) * P.energy * (0.7 + P.scale*0.4);
  fill(dh, st.dotSat*0.7, bri, 10 + tw*16);
  ellipse(px, py, sz*2.6, sz*2.6);
  fill(dh, st.dotSat, bri, 30 + tw*40);
  ellipse(px, py, sz, sz);
  if (tw > 0.85) { fill(dh, st.dotSat*0.3, 100, 70); ellipse(px, py, sz*0.4, sz*0.4); }
}
blendMode(BLEND);
pop();

blendMode(BLEND);
if (drawingContext) drawingContext.shadowBlur = 0;
